var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();
if(EditorApplication.isPlaying || scene.path!="Assets/Proto/MountainPass/Scenes/MountainPass.unity")throw new System.InvalidOperationException("프로토타입 편집 씬을 확인하세요.");
UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene,"Assets/Temp/MountainPassRefinement~/Test_Before.unity",true);
var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();
System.Func<Transform,string> path=null;path=t=>t.parent==null?t.name:path(t.parent)+"/"+t.name;
var shrine=GameObject.Find("MountainPassEnvironment/Shrine_Building_Placement");
var gate=UnityEngine.Object.FindFirstObjectByType<Cheon.Prototype.MountainPass.PassWorldTransition>();
return new{shrine=shrine==null?null:new{position=shrine.transform.position.ToString("F4"),rotation=shrine.transform.eulerAngles.ToString("F4"),parts=shrine.GetComponentsInChildren<Transform>(true).Where(t=>t.GetComponent<Renderer>()!=null).Select(t=>new{path=path(t),position=t.position.ToString("F3"),colliders=t.GetComponents<Collider>().Select(c=>c.GetType().Name).ToArray(),min=t.GetComponent<Renderer>().bounds.min.ToString("F3"),max=t.GetComponent<Renderer>().bounds.max.ToString("F3"),mesh=t.GetComponent<MeshFilter>()!=null?t.GetComponent<MeshFilter>().sharedMesh.name:null}).ToArray()},gatePosition=gate.transform.position.ToString("F4"),gateRotation=gate.transform.eulerAngles.ToString("F4"),gateData=JsonUtility.ToJson(gate),stairs=all.Where(t=>t.name=="Stairway_Winding_Approach"||t.name=="Stairway_Between_Summits").Select(t=>new{path=path(t),mesh=t.GetComponent<MeshFilter>().sharedMesh.name,min=t.GetComponent<Renderer>().bounds.min.ToString("F4"),max=t.GetComponent<Renderer>().bounds.max.ToString("F4")}).ToArray(),lanterns=GameObject.Find("SpiritLanterns").transform.Cast<Transform>().Select(t=>new{t.name,pos=t.position.ToString("F2")}).ToArray()};
